import {useMemo} from '@wordpress/element';
import {applyFilters} from '@wordpress/hooks';
import {getSetting} from '@woocommerce/settings';
import {getStripeAmount, getElementMode} from '@wc-stripe/blocks-utils';

export const useElementOptions = (
    {
        gatewayId,
        cartTotal,
        currency,
        elementOptions,
        expressCheckout = false,
        shouldSavePayment = false,
    }) => {
    const amount = getStripeAmount(cartTotal.value, currency);
    return useMemo(() => {
        const options = {
            currency: currency?.code?.toLowerCase(),
            ...elementOptions
        };
        options.mode = getElementMode({mode: options.mode, amount, shouldSavePayment});
        if (['payment', 'subscription'].includes(options.mode)) {
            options.amount = amount;
        }
        if (expressCheckout) {
            delete options.paymentMethodTypes;
            // Without an explicit configuration, Stripe resolves the account's default configuration.
            const paymentMethodConfiguration = getSetting('stripeGeneralData')?.paymentMethodConfiguration;
            if (paymentMethodConfiguration) {
                options.paymentMethodConfiguration = paymentMethodConfiguration;
            }
        }
        return applyFilters('wc_stripe_blocks_element_options', options, gatewayId);
    }, [
        gatewayId,
        amount,
        currency?.code,
        expressCheckout,
        shouldSavePayment
    ]);
};
