import {registerPaymentMethod} from '@woocommerce/blocks-registry';
import {getSetting} from '@woocommerce/settings';
import {registerExpressPaymentMethod} from '@wc-stripe/blocks-express-checkout';
import {isCartPage} from '@wc-stripe/blocks-utils';
import {canMakePayment, LocalPaymentIntentContent} from '../local-payment-method';
import {ExpressCheckoutContent} from '../../express-checkout';
import {PaymentMethodLabel, PaymentMethod} from "@wc-stripe/blocks-components";
import AmazonPayPreview from './preview';

const data = getSetting('stripe_amazonpay_data');

if (data) {
    const sections = data.sections || [];

    registerPaymentMethod({
        name: data.name,
        label: <PaymentMethodLabel
            title={data.title}
            paymentMethod={data.name}
            icons={data.icon}/>,
        ariaLabel: 'Amazon Pay',
        placeOrderButtonLabel: data.placeOrderButtonLabel,
        canMakePayment: (args) => {
            // Only show in the payment methods list if the Checkout section is enabled.
            if (sections.length && !sections.includes('checkout')) {
                return false;
            }
            return canMakePayment(data.gatewayId)(args);
        },
        content: <PaymentMethod content={LocalPaymentIntentContent} data={data}/>,
        edit: <PaymentMethod content={LocalPaymentIntentContent} data={data}/>,
        supports: {
            showSavedCards: false,
            showSaveOption: false,
            features: data.features
        }
    });

    const activeMethod = {amazonPay: 'auto'};

    registerExpressPaymentMethod({
        name: 'stripe_amazonpay_express',
        gatewayId: data.gatewayId,
        paymentMethodId: data.gatewayId,
        activeMethod,
        availabilityKey: 'amazonPay',
        context: () => isCartPage() ? 'cart' : 'express_checkout',
        sections,
        content: (
            <ExpressCheckoutContent
                data={data}
                name='stripe_amazonpay_express'
                activeMethod={activeMethod}
                confirmationToken={true}
            />
        ),
        edit: <AmazonPayPreview data={data}/>,
        supports: {
            showSavedCards: false,
            showSaveOption: false,
            features: data.features
        }
    });
}