import {useState, useEffect, useRef, useCallback, useReducer} from '@wordpress/element';
import {useElements, useStripe} from "@stripe/react-stripe-js";
import {ensureErrorResponse, ensureSuccessResponse, getBillingDetailsFromAddress} from '@wc-stripe/blocks-utils';
import {
    reducer,
    useEvents,
    emitFilter,
    constants
} from './actions';

/**
 * Creates a Stripe ConfirmationToken from the Elements instance. The server creates the
 * PaymentIntent without a payment method and confirms it using the token.
 *
 * Returns the same keys as useCreatePaymentMethod so the two hooks are interchangeable.
 *
 * @since 4.0.20
 */
export const useCreateConfirmationToken = (
    {
        name,
        gatewayId,
        emitResponse,
        billingAddress,
        shippingAddress,
        eventRegistration,
        activePaymentMethod
    }) => {
    const [confirmationToken, _setConfirmationToken] = useState(null);
    const {onPaymentSetup} = eventRegistration;
    const stripe = useStripe();
    const elements = useElements();

    const [eventCallbacks, dispatch] = useReducer(reducer, {});
    const events = useEvents(dispatch);

    const currentData = useRef({
        billingAddress,
        shippingAddress,
        confirmationToken,
        eventCallbacks
    });

    useEffect(() => {
        currentData.current = {
            ...currentData.current,
            billingAddress,
            shippingAddress,
            confirmationToken,
            eventCallbacks
        };
    }, [
        billingAddress,
        shippingAddress,
        confirmationToken,
        eventCallbacks
    ]);

    const clearConfirmationToken = useCallback(() => {
        _setConfirmationToken(null);
    }, []);

    const createConfirmationToken = useCallback(async () => {
        const {billingAddress, eventCallbacks} = currentData.current;
        try {
            let result = await elements.submit();
            if (result.error) {
                throw result.error;
            }

            const data = await emitFilter({
                elements,
                params: {
                    payment_method_data: {
                        billing_details: {
                            phone: '',
                            email: '',
                            ...getBillingDetailsFromAddress(billingAddress)
                        }
                    }
                }
            }, null, {events: eventCallbacks, type: constants.CREATE_PAYMENT_DATA});

            result = await stripe.createConfirmationToken(data);

            if (result.error) {
                throw result.error;
            }
            _setConfirmationToken(result.confirmationToken);

            return result.confirmationToken;
        } catch (error) {
            clearConfirmationToken();
            throw error;
        }
    }, [
        stripe,
        elements,
        clearConfirmationToken
    ]);

    useEffect(() => {
        const unsubscribe = onPaymentSetup((async () => {
            if (activePaymentMethod !== name) {
                return null;
            }
            const {
                eventCallbacks,
                billingAddress,
                shippingAddress
            } = currentData.current;
            try {
                let token = currentData.current.confirmationToken;
                if (!token?.id) {
                    token = await createConfirmationToken();
                }
                const data = await emitFilter(
                    {
                        meta: {
                            paymentMethodData: {
                                [`${gatewayId}_confirmation_token`]: token.id
                            }
                        }
                    },
                    {confirmationToken: token, billingAddress, shippingAddress},
                    {events: eventCallbacks, type: constants.ADD_SUCCESS_DATA}
                );

                return ensureSuccessResponse(emitResponse.responseTypes, data);
            } catch (error) {
                return ensureErrorResponse(
                    emitResponse.responseTypes,
                    error,
                    {
                        messageContext: emitResponse.noticeContexts.PAYMENTS
                    }
                );
            }
        }));
        return () => {
            unsubscribe();
        };
    }, [
        name,
        gatewayId,
        onPaymentSetup,
        createConfirmationToken,
        activePaymentMethod
    ]);

    return {
        events,
        paymentMethodData: confirmationToken,
        createPaymentMethod: createConfirmationToken,
        clearPaymentMethodData: clearConfirmationToken
    }
}